class Solution {
  public int shortestWay(String source, String target) {
    int count = 0;
    for (int t = 0; t < target.length(); ) {
      int start = t;
      for (int s = 0; s < source.length() && t < target.length(); s++) if (source.charAt(s) == target.charAt(t)) t++;
      if (t == start) return -1; // this character never appears in source
      count++;
    }
    return count;
  }
}
